window.INVENTORY_ACCOUNTING_GROUPS=[{"id": "inventory-cost-agent", "name": "存货成本核算智能体", "desc": "核对存货收发成本、计价依据与成本差异。", "skills": ["查询存货成本", "核对出入库成本", "分析存货成本差异"]}, {"id": "inventory-ledger-agent", "name": "存货账务核对智能体", "desc": "核对存货明细账、总账与关联凭证。", "skills": ["核对存货明细账与总账", "查询存货核算凭证", "检查未过账交易"]}, {"id": "inventory-close-agent", "name": "存货关账智能体", "desc": "检查月末存货核算进度，整理关账前待办。", "skills": ["检查存货关账条件", "整理存货关账清单"]}];
(()=>{
const role=()=>sessionStorage.getItem('yunxu-role')==='inventory-accountant';
const originalHistory=roleSessions;roleSessions=function(){if(role()&&!sessionRecords.some(x=>x.role==='inventory-accountant')){[['存货明细账与总账核对','已整理存货明细账与总账核对范围，可继续补充库存组织和会计期间。'],['查询本期存货成本','可按库存组织、物料与会计期间查询存货成本。']].forEach((x,i)=>sessionRecords.push({id:'inventory-accountant-session-'+i,role:'inventory-accountant',source:'manual',title:x[0],time:Date.now()-i*60000,messages:[{user:false,text:x[1]}]}));saveSessionRecords()}return originalHistory()};
const originalDashboard=applyWarehouseDashboard;applyWarehouseDashboard=function(){originalDashboard();document.querySelector('.ai-suggestions').hidden=role();if(!role())return;document.getElementById('stats').innerHTML=[['待核算批次','12','项'],['待核对凭证','8','笔'],['成本差异','2','项'],['关账进度','75','%']].map(x=>'<div class="stat"><div class="statlabel">'+x[0]+'</div><div class="number">'+x[1]+' <small>'+x[2]+'</small></div><div class="statfoot">当前期间 · 示例数据</div></div>').join('');document.querySelector('.ai-suggestions').innerHTML=[['存货成本','查询本期存货成本'],['账务核对','核对存货明细账与总账'],['差异分析','分析存货成本差异'],['关账检查','检查本期存货关账条件']].map(x=>'<button data-accounting-prompt="'+x[1]+'">'+x[0]+'</button>').join('');document.querySelectorAll('[data-accounting-prompt]').forEach(b=>b.onclick=()=>suggest(b.dataset.accountingPrompt));document.querySelector('.composer-mascot').src='assets/role-asset-admin.png'};
const originalConcerns=renderConcerns;renderConcerns=function(tab){if(!role())return originalConcerns(tab);const el=document.getElementById('concerns');el.innerHTML='<div class="concern-head"><h2>你可能关注</h2><small>存货核算与账务事项</small></div><div class="concern-panel concern-table"><table><thead><tr><th>业务事项</th><th>核对范围</th><th>状态</th></tr></thead><tbody><tr><td>存货明细账与总账核对</td><td>当前会计期间</td><td>待核对</td></tr><tr><td>存货成本差异复核</td><td>2项成本差异</td><td>待确认</td></tr><tr><td>月末存货关账检查</td><td>本期存货交易与凭证</td><td>运行中</td></tr></tbody></table></div>'};
})();
